```javascript
class WeatherCache {
  constructor(ttl = 300000) { // 5 minutes TTL by default
    this.cache = {};
    this.ttl = ttl;
  }

  get(city) {
    if (this.cache[city] && this.cache[city].expires > Date.now()) {
      return this.cache[city].data;
    }
    return null;
  }

  set(city, data) {
    this.cache[city] = {
      data,
      expires: Date.now() + this.ttl
    };
  }
}
```

```javascript
// Alternatively, using localStorage for the last 3 searched cities with timestamps:
const getCachedData = (city) => {
  const cached = JSON.parse(localStorage.getItem('weatherCache')) || {};
  return cached[city] || null;
};

const setCachedData = (city, data) => {
  let cached = JSON.parse(localStorage.getItem('weatherCache')) || {};
  const cities = Object.keys(cached);

  if (cities.length >= 3 && !cached[city]) {
    delete cached[cities[0]];
  }

  cached[city] = {
    ...data,
    timestamp: Date.now()
  };

  localStorage.setItem('weatherCache', JSON.stringify(cached));
};
```

